package gen

import (
	"fmt"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"

	"github.com/junikimm717/static-python/src/staticpy/internal/config"
)

// BuiltinName flattens a dotted module name into the identifier makesetup and
// config.c use.
func BuiltinName(dotted string) string {
	if !strings.Contains(dotted, ".") {
		return dotted
	}
	return "_" + strings.ReplaceAll(dotted, ".", "_")
}

// Shim is one generated file under site-packages.
type Shim struct {
	Path    string // slash-separated, relative to site-packages
	Content []byte
	// Package marks a namespace __init__.py, which must never displace a real
	// one copied from the package's own pure sources.
	Package bool
}

// BuiltinImporter.find_spec returns None whenever path is not None, so `import
// lxml.etree` can never reach a builtin named lxml.etree; the submodule has to
// be a real file that pulls in the flattened builtin and substitutes itself in
// sys.modules.
func Shims(mods []config.PyModule) ([]Shim, error) {
	seen := map[string]bool{}
	var out []Shim
	for _, m := range mods {
		dotted := m.Name
		parts := strings.Split(dotted, ".")
		if len(parts) < 2 {
			continue
		}
		for _, p := range parts {
			if !cIdent.MatchString(p) {
				return nil, fmt.Errorf("gen: %q is not a valid module path", dotted)
			}
		}
		for i := 1; i < len(parts); i++ {
			dir := path.Join(parts[:i]...)
			init := path.Join(dir, "__init__.py")
			if seen[init] {
				continue
			}
			seen[init] = true
			out = append(out, Shim{
				Path:    init,
				Content: []byte("# staticpy: package directory for a bundled builtin extension.\n"),
				Package: true,
			})
		}
		file := path.Join(path.Join(parts[:len(parts)-1]...), parts[len(parts)-1]+".py")
		if seen[file] {
			return nil, fmt.Errorf("gen: duplicate module %q", dotted)
		}
		seen[file] = true
		out = append(out, Shim{Path: file, Content: shimSource(dotted)})
	}
	sort.Slice(out, func(a, b int) bool { return out[a].Path < out[b].Path })
	return out, nil
}

func shimSource(dotted string) []byte {
	return []byte(fmt.Sprintf(`# Generated by staticpy.
import sys, %s
sys.modules[%q] = %s
`, BuiltinName(dotted), dotted, BuiltinName(dotted)))
}

func WriteShims(dir string, shims []Shim) error {
	for _, s := range shims {
		dst := filepath.Join(dir, filepath.FromSlash(s.Path))
		if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
			return err
		}
		if s.Package {
			if _, err := os.Stat(dst); err == nil {
				continue
			}
		}
		if err := os.WriteFile(dst, s.Content, 0o644); err != nil {
			return err
		}
	}
	return nil
}
